const webauthnCredentialsByUserId = `-- name: WebauthnCredentialsByUserId :many
SELECT id, user_id, credential_id, name, credential, sign_count, last_used_at, created_at FROM webauthn_credentials WHERE user_id = $1 ORDER BY id
`

func (q *Queries) WebauthnCredentialsByUserId(ctx context.Context, userID ids.UserID) ([]WebauthnCredential, error) {
	rows, err := q.db.Query(ctx, webauthnCredentialsByUserId, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebauthnCredential{}
	for rows.Next() {
		var i WebauthnCredential
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.CredentialID,
			&i.Name,
			&i.Credential,
			&i.SignCount,
			&i.LastUsedAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
